'use strict';
window.furnishCampus=function({T,P,M,material,box,pbox,rod,solid,root,X,Z,addDoor}){
 const classrooms=[],courtRanks=[],wood=material(0x9d744b,.63,0,'wood'),boardSurface=material(0xecefe8,.38),marker=material(0x315967,.7),wheelRubber=M.rubber;
 function panel(w,h,depth,r,mat){const s=new T.Shape();s.moveTo(-w/2+r,-h/2);s.lineTo(w/2-r,-h/2);s.quadraticCurveTo(w/2,-h/2,w/2,-h/2+r);s.lineTo(w/2,h/2-r);s.quadraticCurveTo(w/2,h/2,w/2-r,h/2);s.lineTo(-w/2+r,h/2);s.quadraticCurveTo(-w/2,h/2,-w/2,h/2-r);s.lineTo(-w/2,-h/2+r);s.quadraticCurveTo(-w/2,-h/2,-w/2+r,-h/2);const mesh=new T.Mesh(new T.ExtrudeGeometry(s,{depth,bevelEnabled:false,curveSegments:5}),mat);mesh.castShadow=mesh.receiveShadow=true;return mesh;}
 function furnitureCollider(group,x,z,w,d,y1,y2,type){const p=new T.Vector3(x,0,z).applyMatrix4(group.matrixWorld),angle=group.rotation.y,wx=Math.abs(Math.cos(angle))*w/2+Math.abs(Math.sin(angle))*d/2,wz=Math.abs(Math.sin(angle))*w/2+Math.abs(Math.cos(angle))*d/2;solid(p.x-wx,p.x+wx,p.z-wz,p.z+wz,group.position.y+y1,group.position.y+y2,type);}
 function chair(x,z,parent,teacher=false){const g=new T.Group();g.position.set(x,0,z);g.rotation.y=teacher?Math.PI:0;parent.add(g);const seat=panel(.43,.42,.024,.045,wood);seat.rotation.x=-Math.PI/2;seat.position.y=.44;g.add(seat);const back=panel(.44,.28,.018,.045,wood);back.position.set(0,.76,.2);back.rotation.x=.12;g.add(back);for(const dx of [-.18,.18])for(const dz of [-.16,.17]){rod([dx,.035,dz],[dx,.44,dz],.014,M.frame,g);box(.04,.035,.04,wheelRubber,dx,.018,dz,g);}for(const dx of [-.18,.18])rod([dx,.3,.17],[dx,.86,.23],.013,M.frame,g);rod([-.18,.4,-.16],[.18,.4,-.16],.012,M.frame,g);furnitureCollider(parent,x,z,.46,.49,0,.94,'class-chair');}
 function desk(x,z,parent,teacher=false){const w=teacher?1.4:1.4,d=teacher?.7:.62,top=panel(w,d,.03,.035,wood);top.rotation.x=-Math.PI/2;top.position.set(x,.73,z);parent.add(top);for(const dx of [-w/2+.06,w/2-.06])for(const dz of [-d/2+.055,d/2-.055]){rod([x+dx,.03,z+dz],[x+dx,.735,z+dz],.016,M.frame,parent);box(.045,.032,.045,wheelRubber,x+dx,.016,z+dz,parent);}rod([x-w/2+.06,.6,z+d/2-.055],[x+w/2-.06,.6,z+d/2-.055],.016,M.frame,parent);if(teacher){box(.025,.42,d-.1,wood,x-w/2+.02,.49,z,parent);box(w-.08,.3,.025,wood,x,.55,z+d/2-.03,parent);box(.34,.11,.46,wood,x+w*.31,.65,z,parent);box(.11,.012,.016,M.metal,x+w*.31,.64,z-.242,parent);}else{rod([x+w/2-.055,.65,z],[x+w/2+.045,.65,z],.009,M.metal,parent);rod([x+w/2+.045,.65,z],[x+w/2+.045,.69,z],.009,M.metal,parent);}furnitureCollider(parent,x,z,w,d,0,.77,teacher?'teacher-desk':'student-desk');}
 function board(parent){const z=.92;box(1.92,1.2,.065,M.frame,0,1.52,z,parent);const face=panel(1.82,1.1,.006,.022,boardSurface);face.position.set(0,1.52,z+.037);parent.add(face);box(1.79,.025,.065,M.metal,0,.95,z+.065,parent);box(.09,.021,.05,M.rubber,.62,.975,z+.065,parent);box(.1,.012,.012,marker,-.6,.975,z+.065,parent);
  for(const dx of [-.83,.83]){rod([dx,.15,z],[dx,2.07,z],.023,M.metal,parent);rod([dx,.14,z-.36],[dx,.14,z+.36],.026,M.frame,parent);for(const dz of [-.32,.32]){box(.032,.1,.045,M.metal,dx,.1,z+dz,parent);const wheel=new T.Mesh(new T.CylinderGeometry(.055,.055,.033,16),wheelRubber);wheel.rotation.z=Math.PI/2;wheel.position.set(dx,.058,z+dz);parent.add(wheel);box(.035,.012,.065,M.metal,dx,.085,z+dz+.012,parent);}}
  furnitureCollider(parent,0,z,2,.78,0,2.15,'rolling-board');return{z,windowGap:.92,movable:false};
 }
 for(const[l,f]of P.floors.entries())for(const r of f.rooms.filter(r=>r.type==='class'&&r.id!=='staff')){const windows=P.windows[l].filter(w=>w.room===r.id&&!w.interior),frontWindow=windows.find(w=>w.axis==='z'&&w.fixed===r.x)||windows.find(w=>w.axis==='z'&&w.fixed===r.x+r.w)||windows.find(w=>w.axis==='x'&&w.fixed===r.y+r.h)||windows[0];
 const front=frontWindow?(frontWindow.axis==='z'?(frontWindow.fixed===r.x?'left':'right'):(frontWindow.fixed===r.y?'top':'bottom')):'left';
 const g=new T.Group(),origin=front==='left'?[r.x,r.y+r.h/2]:front==='right'?[r.x+r.w,r.y+r.h/2]:front==='top'?[r.x+r.w/2,r.y]:[r.x+r.w/2,r.y+r.h];
 g.position.set(X(origin[0]),l*P.storey,Z(origin[1]));g.rotation.y={left:Math.PI/2,right:-Math.PI/2,top:0,bottom:Math.PI}[front];
 root.add(g);g.updateWorldMatrix(true,false);const b=board(g),students=[];desk(-1.15,2.13,g,true);chair(-1.15,1.4,g,true);
  const depth=(front==='left'||front==='right'?r.w:r.h)*P.scale,rows=Math.max(1,Math.min(7,Math.floor((depth-4.7)/1.5)+1)),columns=[-1.3,1.3];for(let row=0;row<rows;row++)for(const x of columns){const z=3.65+row*1.5;desk(x,z,g);for(const offset of [-.36,.36]){chair(x+offset,z+.66,g);students.push({x:x+offset,z,chairZ:z+.66,facing:-1});}}
  classrooms.push({room:r.id,level:l,front,origin,angle:g.rotation.y,hasWindow:!!frontWindow,board:b,teacher:{x:-1.15,z:2.13,facing:1},students,rows,columns:4,doubleDesks:true,deskWidth:1.4,centralAisle:1.2});
 }
 const interiors=window.decorateCampus({T,P,M,material,box,pbox,rod,solid,root,X,Z,addDoor,classrooms,schoolDesk:(g,x,z,t=false)=>desk(x,z,g,t),schoolChair:(g,x,z,t=false)=>chair(x,z,g,t)});
 const decorations=interiors.decorations;
 // Flat paint, slightly above the actual courtyard surfacing; never obstacles.
 const rankPaint=material(0xffe269,.87),canteenPaint=material(0xd6c480,.87);
 function groundText(text,px,py,width=2.2){const c=document.createElement('canvas');c.width=1024;c.height=256;const ctx=c.getContext('2d');ctx.clearRect(0,0,1024,256);ctx.fillStyle='#fff4b7';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='700 '+(text.length>12?68:110)+'px Arial';ctx.fillText(text,512,128);const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;const mesh=new T.Mesh(new T.PlaneGeometry(width,width/4),new T.MeshStandardMaterial({map:tex,transparent:true,roughness:.92,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-1,polygonOffsetUnits:-1}));mesh.rotation.x=-Math.PI/2;mesh.position.set(X(px),.018,Z(py));root.add(mesh);}
 for(const[index,label]of ['6ème','5ème','4ème','3ème'].entries()){const px=700+index*120,start=150,end=275;for(const offset of [-20,20])box(.085,.005,(end-start)*P.scale,rankPaint,X(px+offset),.013,Z((start+end)/2));box(40*P.scale,.005,.085,rankPaint,X(px),.013,Z(start));for(let py=start+22;py<end;py+=22)box(.21,.005,.04,rankPaint,X(px),.013,Z(py));groundText(label,px,start-20,1.95);courtRanks.push({label,px,start,end,type:'class'});}
 const canteen={label:'RÉFECTOIRE',x:1190,y:348,w:175,h:26,type:'dining'};for(const py of [335,361])box(canteen.w*P.scale,.005,.05,canteenPaint,X(canteen.x),.014,Z(py));box(.05,.005,canteen.h*P.scale,canteenPaint,X(canteen.x+canteen.w/2),.014,Z(canteen.y));for(let px=1120;px<1265;px+=22)box(.045,.005,.24,canteenPaint,X(px),.014,Z(canteen.y));groundText('RANG RÉFECTOIRE',1190,322,3.7);courtRanks.push(canteen);
 // Two courtyard benches on the northern edge, keeping the gates and ranks clear.
 function courtBench(px,py){const x=X(px),z=Z(py);for(const dx of [-.8,.8]){box(.065,.45,.57,M.frame,x+dx,.225,z);rod([x+dx,.45,z-.22],[x+dx,.91,z-.27],.025,M.frame);}for(let n=0;n<4;n++)box(1.9,.035,.09,M.wood,x,.46,z-.17+n*.115);for(let n=0;n<3;n++)box(1.9,.105,.028,M.wood,x,.65+n*.135,z-.26);solid(x-1,x+1,z-.31,z+.31,0,1.04,'court-bench');}
 courtBench(770,76);courtBench(1110,76);
 return{classrooms,courtRanks,decorations,interiors};
};
